export function assertOsEnv(env: Record<string, string>): void {
  const errors = checkOsEnv(env);
  if (errors.length > 0) {
    throw new Error(`environment contract violated: ${errors.map((error) => `${error.path}: ${error.message}`).join("; ")}`);
  }
}

